  -- p0 [text L0] In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru (teacher). Each prince was called to stand before the guru and take aim at a bird perched upon a tree branch some distance away."}]}$ob$::jsonb, $ob$In the Mahabharata, the great Hindu epic, five princes were being taught to fire a bow by a guru (teacher). Each prince was called to stand before the guru and take aim at a bird perched upon a tree…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes the tree and its shadow, the location of the bird within the tangle of branches, and is suddenly interrupted by the guru who tells him to stand back with the others. The next of the five, depicted as the strongest, takes his stance and when asked by the guru describes the bird and its features but is asked to stand back as well. The next two follow suit and are quickly returned without taking a shot. Finally, the last prince is called to aim and asked what he sees. He tells the guru that he sees a dark sphere. Eyebrows raised, the guru says “are you sure?”, to which the prince says if he tries, he can see a fringe of color surrounding the sphere but nothing else. He is describing the eye of the bird and notices nothing else in the rich scene before him. The guru waved his approval, the arrow fired, and the target struck."}]}$ob$::jsonb, $ob$The guru asked each, “tell me what you see”. The eldest, often depicted as the wisest, describes the tree and its shadow, the location of the bird within the tangle of branches, and is suddenly…$ob$, 1, false, NULL, NULL, false, 0);
  -- p2 [figure 1] Figure 1. The guru and princes by Nandalal Bose
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
