  -- p3 [text L0] This story and many others illustrate a series of fundamental puzzles of cognition: Why can we on
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"This story and many others illustrate a series of fundamental puzzles of cognition: Why can we only fully perceive one thing at a time, even though our eyes (or ears, nose, tongue, and skin) take it all in at once? Why do different people (or animals) see the same scene in different ways? Why does perceiving one thing well make the rest fall away? The answer is attention, and decades of study reveal that it allows the brain to focus on the most important information to the task at hand."}]}$ob$::jsonb, $ob$This story and many others illustrate a series of fundamental puzzles of cognition: Why can we only fully perceive one thing at a time, even though our eyes (or ears, nose, tongue, and skin) take it…$ob$, 3, false, NULL, NULL, false, 0);

  -- Section 1: The story of attention
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
