  -- p0 [text L0] Hundreds of years after the princes and the bird, the most influential philosophers writing in En
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Hundreds of years after the princes and the bird, the most influential philosophers writing in English had given attention almost nothing to do. Locke, Hume, Hartley, and other great empiricists built the mind out of sensation and association alone. These writers saw the mind as a passive recipient of experience, shaped entirely by what fell upon the senses from outside."}]}$ob$::jsonb, $ob$Hundreds of years after the princes and the bird, the most influential philosophers writing in English had given attention almost nothing to do. Locke, Hume, Hartley, and other great empiricists…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [text L0] William James, the so-called father of American psychology, writing in 1890, felt this view absur
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"William James, the so-called father of American psychology, writing in 1890, felt this view absurd. Imagine, he proposed, a litter of dogs raised in the Vatican, marble sculpture presented to their eyes in every conceivable form and combination for generation after generation. If experience alone shaped the mind, these dogs ought eventually to become connoisseurs of sculpture. They do not, he posited, because something selective stands between what the eyes receive and what the mind comes to know."}]}$ob$::jsonb, $ob$William James, the so-called father of American psychology, writing in 1890, felt this view absurd. Imagine, he proposed, a litter of dogs raised in the Vatican, marble sculpture presented to their…$ob$, 1, false, NULL, NULL, false, 0);
  -- p2 [text L0] As is often the case with science, that “something” had already been caught in the act, twenty-th
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"As is often the case with science, that “something” had already been caught in the act, twenty-three years earlier by the famous German physiologist Hermann von Helmholtz who asked whether attention could move without the eyes moving. He sat in a darkened room, fixed his gaze on a single point, and arranged a printed sheet of letters in front of him, invisible until a brief electric spark lit the room for an instant — too brief for any eye movement to occur. Before each flash, Helmholtz silently chose where on the sheet he would direct his attention and found the letters readable when the room lit up (well in the afterimage of it anyway). However, other letters, equally close to his fixation point, were lost to him entirely. Helmholtz’s eyes had not moved; only attention had. Selection, it turned out, was not something the eyes did. It was something the brain did independently."}]}$ob$::jsonb, $ob$As is often the case with science, that “something” had already been caught in the act, twenty-three years earlier by the famous German physiologist Hermann von Helmholtz who asked whether attention…$ob$, 2, false, NULL, NULL, false, 0);

