  -- p1 [text L1] How do we follow one conversation in a noisy room while ignoring all others — and why does our ow
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"How do we follow one conversation in a noisy room while ignoring all others — and why does our own name, spoken across that room, still catch our attention? This is the cocktail party problem, named by the British engineer Colin Cherry in 1953, and it became the founding question of experimental attention research"},{"type":"citation_ref","number":1},{"type":"text","content":"."}]}$ob$::jsonb, $ob$How do we follow one conversation in a noisy room while ignoring all others — and why does our own name, spoken across that room, still catch our attention? This is the cocktail party problem, named…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] Cherry's method was to present different speech passages simultaneously to each ear through headp
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Cherry's method was to present different speech passages simultaneously to each ear through headphones and ask participants to repeat the message in one ear alone. Participants did this easily but retained almost nothing from the rejected ear even when it switched to a foreign language. Physical properties of the sound crossed into awareness; meaning did not. Donald Broadbent formalized this in 1958 with the first mechanistic model of selective attention: incoming stimuli are held briefly in a pre-attentive buffer and passed through a bottleneck that passed one channel on the basis of physical features (e.g. <em>pitch, location, voice</em>) and blocked the rest from further processing"},{"type":"citation_ref","number":2},{"type":"text","content":"."}]}$ob$::jsonb, $ob$Cherry's method was to present different speech passages simultaneously to each ear through headphones and ask participants to repeat the message in one ear alone. Participants did this easily but…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed tha
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed that participants heard their own name on the unattended ear about thirty percent of the time, which an absolute gate cannot explain. In other words, the name must have been recognized as meaningful before it could be privileged"},{"type":"citation_ref","number":3},{"type":"text","content":". Anne Treisman extended this challenge by showing that if the attended and unattended channels swapped mid-stream, participants sometimes continued shadowing a word that had just crossed to the ignored side; bilingual listeners occasionally noticed that the rejected channel carried a translation of what they were attending"},{"type":"citation_ref","number":4},{"type":"text","content":". Treisman proposed that Broadbent’s filter attenuates rather than blocks the unattended channel, with individual words (like names) carrying permanently low recognition thresholds. Yet another proposal suggested that all incoming information reaches full perceptual analysis, and selection operates only at the level of memory and response"},{"type":"citation_ref","number":5},{"type":"text","content":". A more recent aspect of this debate showed that the degree of suppression of unattended information scales with the processing demands of the attended task"},{"type":"citation_ref","number":6},{"type":"text","content":". While these studies suggested that attention is graded and capacity-dependent, a major limitation remained: measures of selection were inferred from what a listener did or did not report."}]}$ob$::jsonb, $ob$Broadbent's all-or-nothing filter did not survive experimental scrutiny. Neville Moray showed that participants heard their own name on the unattended ear about thirty percent of the time, which an…$ob$, 3, false, NULL, NULL, false, 1);
