  -- p6 [text L1] When listeners fail to report something, its origin is ambiguous. When participants missed their 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"When listeners fail to report something, its origin is ambiguous. When participants missed their name on the unattended channel 2/3 times, was it because they failed to detect it? Or did it register, but just not enough to cross the threshold for reporting it? To distinguish these scenarios requires signal detection theory."}]}$ob$::jsonb, $ob$When listeners fail to report something, its origin is ambiguous. When participants missed their name on the unattended channel 2/3 times, was it because they failed to detect it? Or did it…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [level-1 header] Signal detection theory
