  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Signal detection theory"}]}$ob$::jsonb, $ob$Signal detection theory$ob$, 7, false, NULL, NULL, true, 1);
  -- p8 [text L1] Signal detection theory (SDT) originated in in the radar stations of World War II, where engineer
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Signal detection theory (SDT) originated in in the radar stations of World War II, where engineers needed to know how reliably a human operator could detect an enemy aircraft signal against a background of noise"},{"type":"citation_ref","number":7},{"type":"text","content":". The theory was adapted for perceptual psychology by Tanner and Swets in 1954 and developed in full by Green and Swets in 1966."}]}$ob$::jsonb, $ob$Signal detection theory (SDT) originated in in the radar stations of World War II, where engineers needed to know how reliably a human operator could detect an enemy aircraft signal against a…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] SDT’s core insight is that every perceptual judgment involves two independent quantities: d′ (d-p
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"SDT’s core insight is that every perceptual judgment involves two independent quantities: d′ (d-prime), a measure of the observer's true sensitivity — how well the signal is separated from the noise in the nervous system — and criterion, the internal threshold the observer sets for deciding whether a signal is present, which can shift depending on instructions, expectations, or the cost of errors. A cautious observer and a liberal one may have identical sensitivity but very different hit rates and false alarm rates; SDT disentangles the two by analyzing the full pattern of responses across signal-present and signal-absent trials. When attention is directed to a stimulus location or feature, d′ increases — the signal becomes more discriminable — and, independently, criterion can shift. This distinction matters enormously for interpreting attention experiments: an attentional manipulation that quickens reaction times or increases hit rates may be changing sensitivity, changing response strategy, or both. SDT tells you which."}]}$ob$::jsonb, $ob$SDT’s core insight is that every perceptual judgment involves two independent quantities: d′ (d-prime), a measure of the observer's true sensitivity — how well the signal is separated from the noise…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [widget sdt] Interactive: Signal Detection Theory
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"widget","widgetId":"sdt","kind":"breakout","title":"Signal Detection Theory","blurb":"Drag the criterion, adjust d′, and watch the ROC curve respond. Demonstrates how sensitivity and bias are independent.","credit":"Arjun Krishnaswamy","route":"/sdt","placementId":"attention-sdt"}]}$ob$::jsonb, $ob$Interactive: Signal Detection Theory$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [text L1] Signal detection theory models “noise” and “signal” as a pair of overlapping Gaussian distributi
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Signal detection theory models “noise” and “signal” as a pair of overlapping Gaussian distributions along a single \"evidence\" or “stimulus” axis. Since signal and noise distributions overlap, no single level of activity belongs unambiguously to one or the other. Observers respond to evidence exceeding a <em>criterion</em>. Internal responses from the signal distribution that clear the criterion are <em>hits</em>; those from the noise one are <em>false alarms</em>. Lowering criterion catches more signal but also raises false alarms; raising it does the reverse. Thus, criterion reflects strategy, not perception, and shifts with instructions, expectations, and the cost of errors."}]}$ob$::jsonb, $ob$Signal detection theory models “noise” and “signal” as a pair of overlapping Gaussian distributions along a single "evidence" or “stimulus” axis. Since signal and noise distributions overlap, no…$ob$, 11, false, NULL, NULL, false, 1);
  -- p12 [text L1] The distance between the arithmetic means of the two distributions is d′ (d-prime). It is measur
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The distance between the arithmetic means of the two distributions is <em>d′</em> (d-prime). It is measured in units of standard deviation and captures how discriminable the signal is from the noise. Thus, d’ reflects the observer's sensitivity independent of criterion. Both quantities can be recovered from just two measured numbers, the hit rate <em>H</em> and the false-alarm rate <em>F</em>:"}]}$ob$::jsonb, $ob$The distance between the arithmetic means of the two distributions is d′ (d-prime). It is measured in units of standard deviation and captures how discriminable the signal is from the noise. Thus,…$ob$, 12, false, NULL, NULL, false, 1);
  -- p13 [text L1] z is the inverse of the normal distribution which converts a rate (hit or false alarm) into a di
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<em>z</em> is the inverse of the normal distribution which converts a rate (hit or false alarm) into a distance along the evidence axis. Thus, the same two measurements are used in complementary (and orthogonal) ways: their <em>difference</em> gives sensitivity, <em>d′</em>, while their <em>sum</em> gives the criterion, <em>c</em>."}]}$ob$::jsonb, $ob$z is the inverse of the normal distribution which converts a rate (hit or false alarm) into a distance along the evidence axis. Thus, the same two measurements are used in complementary (and…$ob$, 13, false, NULL, NULL, false, 1);
  -- p14 [text L1] Plotting hit rate against false-alarm rate as the criterion sweeps across its full range traces 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Plotting hit rate against false-alarm rate as the criterion sweeps across its full range traces the <em>receiver operating characteristic</em> (ROC) curve, whose bow away from the diagonal is the signature of sensitivity: the further from the diagonal, the larger the <em>d′</em>."}]}$ob$::jsonb, $ob$Plotting hit rate against false-alarm rate as the criterion sweeps across its full range traces the receiver operating characteristic (ROC) curve, whose bow away from the diagonal is the signature…$ob$, 14, false, NULL, NULL, false, 1);
  -- p15 [level-1 header] Attention improves discriminability and reaction time
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Attention improves discriminability and reaction time"}]}$ob$::jsonb, $ob$Attention improves discriminability and reaction time$ob$, 15, false, NULL, NULL, true, 1);
  -- p16 [text L1] The cocktail party experiments established the phenomenon of selection and SDT provided the tool
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The cocktail party experiments established the phenomenon of selection and SDT provided the tools to measure it precisely. However, by the 1980s, scientists had moved from the auditory stimuli to visual ones to take advantage of the better spatial control this modality offered. A key question was to understand what attention does to the perceptual quality of the selected signal."}]}$ob$::jsonb, $ob$The cocktail party experiments established the phenomenon of selection and SDT provided the tools to measure it precisely. However, by the 1980s, scientists had moved from the auditory stimuli to…$ob$, 16, false, NULL, NULL, false, 1);
  -- p17 [text L1] The spatial cueing paradigm introduced by Michael Posner in 1980 became a major tool to answer t
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The spatial cueing paradigm introduced by Michael Posner in 1980 became a major tool to answer this question"},{"type":"citation_ref","number":8},{"type":"text","content":". Briefly, subjects detect a visual target appearing somewhere on a screen following a visual cue (eg: an arrow indicating where a target will appear, or flash at the target’s eventual location). On most trials the cue is valid, and the target appears at the cued location. However, on a small portion of trials the cue is invalid, and the target appears elsewhere. As subjects responded, Posner tracked their eye position to confirm it stayed fixed throughout."}]}$ob$::jsonb, $ob$The spatial cueing paradigm introduced by Michael Posner in 1980 became a major tool to answer this question. Briefly, subjects detect a visual target appearing somewhere on a screen following a…$ob$, 17, false, NULL, NULL, false, 1);
  -- p18 [figure 3] Figure 3. Posner Invalid Cueing task
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":3,"caption":"Posner Invalid Cueing task"},{"type":"text","content":". Posner Invalid Cueing task"}]}$ob$::jsonb, $ob$Figure 3. Posner Invalid Cueing task$ob$, 18, true, v_fig_3, 'auto', false, 1);
  -- p19 [text L1] He learned that valid cues speed detection relative to neutral trials (target appears without cu
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"He learned that valid cues speed detection relative to neutral trials (target appears without cue), and invalid cues slow it — and crucially, this cost/benefit pattern held with no eye movements at all, confirming that covert attention alone, not gaze, was responsible. This was Helmholtz's observation made quantitative: attention moves freely and rapidly through space, and its deployment has measurable consequences for perception."}]}$ob$::jsonb, $ob$He learned that valid cues speed detection relative to neutral trials (target appears without cue), and invalid cues slow it — and crucially, this cost/benefit pattern held with no eye movements at…$ob$, 19, false, NULL, NULL, false, 1);
  -- p20 [text L1] While Posner's original measurements were in reaction time alone, subsequent SDT work showed tha
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"While Posner's original measurements were in reaction time alone"},{"type":"citation_ref","number":8},{"type":"text","content":", subsequent SDT work showed that cueing increases <em>d′</em> (it improves discriminability of signal from noise) without altering the observer's willingness to respond"},{"type":"citation_ref","number":9},{"type":"text","content":" (ie; criterion). Together, these results indicate that spatial attention simultaneously quickens responses and raises discriminability, a dual signature that places strong constraints on any neural account of the mechanism."}]}$ob$::jsonb, $ob$While Posner's original measurements were in reaction time alone, subsequent SDT work showed that cueing increases d′ (it improves discriminability of signal from noise) without altering the…$ob$, 20, false, NULL, NULL, false, 1);

  -- Section 3: Neural Correlates of Visual Attention.
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Neural Correlates of Visual Attention.$ob$, $ob$neural-correlates-of-visual-attention$ob$, 3, NULL);
  -- p0 [text L0] The earliest attentional signatures were found in a primate midbrain structure called the superio
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The earliest attentional signatures were found in a primate midbrain structure called the superior colliculus whose neurons showed enhanced responses when a stimulus in the receptive field was about to become a saccade target (goldberg and wurtz, 1972). Approximately a decade later the same effects were seen independent of eye movement (bushnell, Goldberg, Robinson, 1981). Subsequent work defined these effects as “overt” (associated with eye movement) and “covert” (no eye movement). This effort also defined attention to visual locations (spatial attention), to visual features (feature attention), and to visual objects (object attention). Spatial attention paradigms (such as the posner cueing method) were the earliest adopted and are still the most widely used. As a result, much of what we know about the neural correlates of visual attention arise from the spatial cueing paradigm. Below we describe these single-neuron and population level effects in the context of covert spatial attention, and then we turn to similarities and differences produced by feature/object attention."}]}$ob$::jsonb, $ob$The earliest attentional signatures were found in a primate midbrain structure called the superior colliculus whose neurons showed enhanced responses when a stimulus in the receptive field was about…$ob$, 0, false, NULL, NULL, false, 0);
  -- p1 [level-1 header] Stimuli evoke stronger firing from visual neurons when attention is directed to their rece
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Stimuli evoke stronger firing from visual neurons when attention is directed to their receptive field."}]}$ob$::jsonb, $ob$Stimuli evoke stronger firing from visual neurons when attention is directed to their receptive field.$ob$, 1, false, NULL, NULL, true, 1);
  -- p2 [text L1] Many studies indicate that covertly attending a spatial location enhances the firing of visual ne
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Many studies indicate that covertly attending a spatial location enhances the firing of visual neurons whose receptive fields overlap such locations. The magnitude of these effects at different stations of the visual pathway vary but can be seen in many animals as early as the lateral geniculate nucleus of the thalamus. Such attentional enhancements become more pronounced as one moves up the visual hierarchy and in primates is most strong at the highest visual areas. Early work on the topic employed cueing paradigms and single unit recordings from awake behaving non-human primates. These studies consistently turned up two forms of attention related changes to neural firing termed contrast and response gain."}]}$ob$::jsonb, $ob$Many studies indicate that covertly attending a spatial location enhances the firing of visual neurons whose receptive fields overlap such locations. The magnitude of these effects at different…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Contrast gain causes left-ward shifts of the neural stimulus response function. The visual system
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Contrast gain causes left-ward shifts of the neural stimulus response function. The visual system is attuned to contrast and many neurons, including those within the cortex, increase their firing as stimulus contrast grows (Figure XX). The relationship often adopts a sigmoid shape: the neural response follows stimulus contrast linearly in a narrow band of values, below this band neurons rarely respond, above this bad their responses saturate. In many ways, such neurometric curves, were analogous to the psychometric curves computed for an entire animal’s response to stimuli."}]}$ob$::jsonb, $ob$Contrast gain causes left-ward shifts of the neural stimulus response function. The visual system is attuned to contrast and many neurons, including those within the cortex, increase their firing as…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [figure 4] Figure 4. Contrast vs response gain
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":4,"caption":"Contrast vs response gain"},{"type":"text","content":". Contrast vs response gain"}]}$ob$::jsonb, $ob$Figure 4. Contrast vs response gain$ob$, 4, true, v_fig_4, 'auto', false, 1);
  -- p5 [text L1] Such stimulus-response curves are shifted left when attention is placed upon a stimulus residing 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Such stimulus-response curves are shifted left when attention is placed upon a stimulus residing in the receptive field (Figure XX). If attention is directed outside the receptive field, the curve shifts to the right. These shifts change neural firing in ways that mimic an effective increase in stimulus contrast and were observed at both neural and behavioral levels. These results suggested that the neural mechanisms underlying spatial attention may be the same mechanisms activated by strong versus weak stimuli."}]}$ob$::jsonb, $ob$Such stimulus-response curves are shifted left when attention is placed upon a stimulus residing in the receptive field (Figure XX). If attention is directed outside the receptive field, the curve…$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [text L1] Response gain increases a neural responses across all kinds of attended stimuli. A separate, but 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Response gain increases a neural responses across all kinds of attended stimuli. A separate, but parallel line of inquiry showed a very different effect of attention –under certain conditions, both the psychometric curve of subjects and the neurometric curves obtained from recordings would show a vertical stretching (figure XX). The curves obtained when attention was directed into the receptive field of a neuron were consistent with a multiplication of that neuron’s stimulus-response function. Thus, attention in these experiments was seen as an increase in the excitability of neurons rather than the change in stimulus sensitivity produced by contrast gain."}]}$ob$::jsonb, $ob$Response gain increases a neural responses across all kinds of attended stimuli. A separate, but parallel line of inquiry showed a very different effect of attention –under certain conditions, both…$ob$, 6, false, NULL, NULL, false, 1);
  -- p7 [text L1] Attention biases competition between two stimuli residing in the same receptive field. Macaque br
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Attention biases competition between two stimuli residing in the same receptive field. Macaque brain area V4 had become the premier model for these studies because the large receptive fields of V4 neurons (~60degrees) made their responses to stimuli relatively immune to small eye movements. However, this large size meant that studies of contrast and response gain required subjects to move attention to the other hemifield to be well clear of any overlap with the recorded cells receptive field. As understanding grew, the large size of these receptive fields proved to be a sticky issue. Specifically, researchers began asking what happens when attention must select among stimuli competing within the same receptive field as occurs during visual search?"}]}$ob$::jsonb, $ob$Attention biases competition between two stimuli residing in the same receptive field. Macaque brain area V4 had become the premier model for these studies because the large receptive fields of V4…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [text L1] Moran and Desimone (1985) tested this directly by placing a behaviorally relevant and irrelevant 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Moran and Desimone (1985) tested this directly by placing a behaviorally relevant and irrelevant stimulus within a single V4 neuron's receptive field and asking a subject to move attention between them. The two stimuli differed along dimensions of the neuron’s selectivity (ie: color and orientation) so that one was a \"good\" stimulus that drove the cell strongly on its own and the other a \"poor\" stimulus that drove it weakly. When attention directed outside the receptive field, the neuron's response to the pair fell to a level between that evoked by either stimulus alone. When the monkey attended to the good stimulus, the paired response rose toward the level evoked by that stimulus alone; when attention shifted to the poor stimulus, the paired response fell toward that stimulus's lower evoked firing rate. In each case the neuron's output came to resemble its response to the attended stimulus in isolation. It is as though the unattended stimulus had been filtered out of its receptive field entirely. (FigureYY)"}]}$ob$::jsonb, $ob$Moran and Desimone (1985) tested this directly by placing a behaviorally relevant and irrelevant stimulus within a single V4 neuron's receptive field and asking a subject to move attention between…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [figure 5] Figure 5. Attention biases competition between stimuli in the receptive field
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":5,"caption":"Attention biases competition between stimuli in the receptive field"},{"type":"text","content":". Attention biases competition between stimuli in the receptive field"}]}$ob$::jsonb, $ob$Figure 5. Attention biases competition between stimuli in the receptive field$ob$, 9, true, v_fig_5, 'auto', false, 1);
  -- p10 [text L1] Attention to a visual feature enhances neural firing in ways similar to spatial attention. Atten
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Attention to a visual feature enhances neural firing in ways similar to spatial attention. Attention to a visual feature enhances neural firing in ways similar to spatial attention, but the underlying computation differs. Treue and Martinez-Trujillo (1999) recorded from neurons in the motion-sensitive area MT while two patches of moving dots were displayed, one positioned inside a neuron's receptive field and the other in the opposite hemifield, entirely outside it (figureZZ). On each trial the monkey attended either to the fixation point or to the patch outside the receptive field, and the two patches always moved in the same direction. Although the recorded neuron's receptive field always contained the same physical stimulus, its firing rate changed depending on the direction of the attended patch elsewhere in the visual field: responses rose when the attended direction matched the neuron's preferred direction and fell when it matched the neuron's null direction. Because the attended stimulus never entered the receptive field, this modulation could not be a spatial effect. Instead, it depended only on the attended feature (motion direction)."}]}$ob$::jsonb, $ob$Attention to a visual feature enhances neural firing in ways similar to spatial attention. Attention to a visual feature enhances neural firing in ways similar to spatial attention, but the…$ob$, 10, false, NULL, NULL, false, 1);
  -- p11 [figure 6] Figure 6. Feature Attention
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"figure_placeholder","number":6,"caption":"Feature Attention"},{"type":"text","content":". Feature Attention"}]}$ob$::jsonb, $ob$Figure 6. Feature Attention$ob$, 11, true, v_fig_6, 'auto', false, 1);
  -- p12 [text L1] This push-pull pattern led Treue and Martinez-Trujillo to propose the feature-similarity gain pr
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"This push-pull pattern led Treue and Martinez-Trujillo to propose the feature-similarity gain principle: attention multiplies a neuron's response by a gain factor set by the similarity between the attended feature and the neuron's own tuning preference."}]}$ob$::jsonb, $ob$This push-pull pattern led Treue and Martinez-Trujillo to propose the feature-similarity gain principle: attention multiplies a neuron's response by a gain factor set by the similarity between the…$ob$, 12, false, NULL, NULL, false, 1);
  -- p13 [text L1] Normalization model: are the many forms of attentional modulation different mechanisms, or are t
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Normalization model: are the many forms of attentional modulation different mechanisms, or are they facets of the same process? Starting in the early 2000s, the field was trying to reconcile the many different forms of attention and their neural correlates. The question being asked was whether contrast/response gain, biased competition, feature similarity, and others, reflected different underlying mechanisms of visual attention or were in fact the same phenomenon. A big clue would emerge from computational studies of visual cortical neurons which revealed the normalization-like logic of their firing to visual stimuli."}]}$ob$::jsonb, $ob$Normalization model: are the many forms of attentional modulation different mechanisms, or are they facets of the same process? Starting in the early 2000s, the field was trying to reconcile the…$ob$, 13, false, NULL, NULL, false, 1);
  -- p14 [text L1] Normalization was first formalized as a mechanism for gain control in primary visual cortex, whe
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Normalization was first formalized as a mechanism for gain control in primary visual cortex, where a neuron's response is computed from both its own input divided by the pooled activity of a wider population of neighboring neurons (Heeger, 1992). This divisive step endows visual neurons with unique coding properties that include invariance to certain stimulus dimensions (contrast), high-sensitivity, and winner-take-all behavior. This latter feature is particularly relevant to attention since earlier work indicated that presentation of two stimuli in the receptive field evoked activity that was an average of that evoked by either stimulus alone. However, attending to one of these stimuli led its activity pattern to dominate firing behavior."}]}$ob$::jsonb, $ob$Normalization was first formalized as a mechanism for gain control in primary visual cortex, where a neuron's response is computed from both its own input divided by the pooled activity of a wider…$ob$, 14, false, NULL, NULL, false, 1);
  -- p15 [text L1] Reynolds and Heeger (2009) proposed that attention acts directly on the normalization computatio
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Reynolds and Heeger (2009) proposed that attention acts directly on the normalization computation. In their model, attention adds an extra gain field over the population of neurons — a spatially or feature-selective region where inputs are boosted before they are pooled for normalization. Whether this produces contrast gain or response gain depends on the size of the stimulus relative to the size of the attention field: a small stimulus attended by a wide field yields contrast gain, a large stimulus attended by a narrow field yields response gain, and every intermediate combination is possible in between. The same architecture, applied to two stimuli sharing a receptive field, reproduces biased competition; applied to a field defined by feature rather than location, it reproduces the feature-similarity gain principle. A single computation, run under different conditions, accounts for all four phenomena described above."}]}$ob$::jsonb, $ob$Reynolds and Heeger (2009) proposed that attention acts directly on the normalization computation. In their model, attention adds an extra gain field over the population of neurons — a spatially or…$ob$, 15, false, NULL, NULL, false, 1);
  -- p16 [widget normalization-model] Interactive: Normalization model of attention
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"widget","widgetId":"normalization-model","kind":"breakout","title":"Normalization model of attention","blurb":"Interactive normalization model showing how attention modulates neural responses through divisive normalisation — the unifying computation.","credit":"Arjun Krishnaswamy","route":"","placementId":"attention-normalization-model"}]}$ob$::jsonb, $ob$Interactive: Normalization model of attention$ob$, 16, false, NULL, NULL, false, 1);
