  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"A neuron's response, r, depends on the stimulus's contrast, c:"}]}$ob$::jsonb, $ob$A neuron's response, r, depends on the stimulus's contrast, c:$ob$, 18, false, NULL, NULL, false, 2);
