  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"σ = threshold contrast to evoke a neural response."}]}$ob$::jsonb, $ob$σ = threshold contrast to evoke a neural response.$ob$, 21, false, NULL, NULL, false, 2);
  -- p22 [text L2] The denominator isn't just this neuron's own input, rather, it is a sum over a whole neighborhoo
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The denominator isn't just this neuron's own input, rather, it is a sum over a whole neighborhood of nearby neurons, pooled together to keep responses in a workable range. Attention adds a gain, γ (always greater than 1), but that gain only reaches whatever falls inside the attention field."}]}$ob$::jsonb, $ob$The denominator isn't just this neuron's own input, rather, it is a sum over a whole neighborhood of nearby neurons, pooled together to keep responses in a workable range. Attention adds a gain, γ…$ob$, 22, false, NULL, NULL, false, 2);
  -- p23 [text L2] Whether it produces contrast gain or response gain comes down to one question: does the attentio
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Whether it produces contrast gain or response gain comes down to one question: <strong>does the attention field also reach the neighborhood being pooled for suppression, or does it stay local to just this one input?</strong>"}]}$ob$::jsonb, $ob$Whether it produces contrast gain or response gain comes down to one question: does the attention field also reach the neighborhood being pooled for suppression, or does it stay local to just this…$ob$, 23, false, NULL, NULL, false, 2);
  -- p24 [text L2] A narrow attention field produces response gain. If the boost lands mostly on this neuron's own 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>A narrow attention field produces response gain.</strong> If the boost lands mostly on this neuron's own input and not on the pooled neighborhood response, the denominator barely changes but the numerator grows. This scales the whole contrast response function upward at every contrast."}]}$ob$::jsonb, $ob$A narrow attention field produces response gain. If the boost lands mostly on this neuron's own input and not on the pooled neighborhood response, the denominator barely changes but the numerator…$ob$, 24, false, NULL, NULL, false, 2);
  -- p25 [text L2] A broad attention field produces contrast gain: If the boost lands on the neuron’s input and the
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"<strong>A broad attention field produces contrast gain</strong>: If the boost lands on the neuron’s input and the whole pooled neighborhood too, then the entire fraction is multiplied which is the same lowering the neuron’s threshold, thereby shifting the contrast response function left."}]}$ob$::jsonb, $ob$A broad attention field produces contrast gain: If the boost lands on the neuron’s input and the whole pooled neighborhood too, then the entire fraction is multiplied which is the same lowering the…$ob$, 25, false, NULL, NULL, false, 2);
