  -- Section 4: Population effects of visual attention
  v_section_id := gen_random_uuid();
  INSERT INTO sections (id, module_id, title, slug, order_index, introduction_text)
  VALUES (v_section_id, v_module_id, $ob$Population effects of visual attention$ob$, $ob$population-effects-of-visual-attention$ob$, 4, NULL);
  -- p0 [level-1 header] Attention improves signal to noise ratio by reducing shared variability among neurons.
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Attention improves signal to noise ratio by reducing shared variability among neurons."}]}$ob$::jsonb, $ob$Attention improves signal to noise ratio by reducing shared variability among neurons.$ob$, 0, false, NULL, NULL, true, 1);
  -- p1 [text L1] Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that f
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that fires more strongly to the attended stimulus also fires more variably from trial to trial. This means that attentional increases in gain apply to signal and noise equally. In principle this need not matter, since the brain could average across many enhanced neurons and thereby reduce noise. However, averaging only works if each neuron's noise is uncorrelated with that of its neighbors. This is not the case for visual neurons, particularly those with overlapped receptive fields which tend to fluctuate together."}]}$ob$::jsonb, $ob$Increasing the responsiveness of neurons during attention, carries a hidden cost: a neuron that fires more strongly to the attended stimulus also fires more variably from trial to trial. This means…$ob$, 1, false, NULL, NULL, false, 1);
  -- p2 [text L1] This shared fluctuation is measured as the noise correlation: the correlation between two neurons
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"This shared fluctuation is measured as the noise correlation: the correlation between two neurons' spike counts across repeated presentations of the same stimulus under the same task conditions. Because the stimulus is identical on every trial, whatever covaries between the two neurons is not stimulus-driven. Since this noise is common to the pair, it survives any subsequent averaging and sets a ceiling on the sensitivity a population can reach."}]}$ob$::jsonb, $ob$This shared fluctuation is measured as the noise correlation: the correlation between two neurons' spike counts across repeated presentations of the same stimulus under the same task conditions.…$ob$, 2, false, NULL, NULL, false, 1);
  -- p3 [text L1] Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during sp
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during spatial attention tasks, two groups found that noise correlations fell by roughly 40% when attention was directed into the neurons' shared receptive field (Cohen and Maunsell, 2009; Mitchell, Sundberg, and Reynolds, 2009). This is a much larger effect than attention had on the same neurons' firing rates (under 20%) or on the variability of each neuron considered alone (under 10%)."}]}$ob$::jsonb, $ob$Recent work indicates that attention lowers this ceiling. Recording pairs of V4 neurons during spatial attention tasks, two groups found that noise correlations fell by roughly 40% when attention…$ob$, 3, false, NULL, NULL, false, 1);
  -- p4 [text L1] The size of these three changes maps onto how much each contributes to the population. Cohen and 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The size of these three changes maps onto how much each contributes to the population. Cohen and Maunsell (2009) recorded groups of V4 neurons simultaneously and measured how well the population discriminated between two stimuli, then asked which physiological change accounted for the attention-related improvement in that measure. The reduction in noise correlation accounted for over 80% of it. Across recording sessions, the improvement in population sensitivity tracked the improvement in the monkey's psychophysical threshold, though this relationship is correlational; no experiment has yet manipulated noise correlations directly to test whether they cause the behavioral gain."}]}$ob$::jsonb, $ob$The size of these three changes maps onto how much each contributes to the population. Cohen and Maunsell (2009) recorded groups of V4 neurons simultaneously and measured how well the population…$ob$, 4, false, NULL, NULL, false, 1);
  -- p5 [text L1] The same pattern holds for feature attention. Recording V4 populations while monkeys alternated b
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The same pattern holds for feature attention. Recording V4 populations while monkeys alternated between spatial and feature attention tasks, Cohen and Maunsell (2011a) found that pairs showing the largest rate increases showed the largest correlation decreases, and pairs whose rates fell showed correlations rise instead. Rate and correlation move together in both forms of attention, suggesting that whatever mechanism produces gain also produces decorrelation."}]}$ob$::jsonb, $ob$The same pattern holds for feature attention. Recording V4 populations while monkeys alternated between spatial and feature attention tasks, Cohen and Maunsell (2011a) found that pairs showing the…$ob$, 5, false, NULL, NULL, false, 1);
  -- p6 [level-1 header] Populations of neurons reveal highly dynamic fluctuations in attention state
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"heading","level":3,"content":"Populations of neurons reveal highly dynamic fluctuations in attention state"}]}$ob$::jsonb, $ob$Populations of neurons reveal highly dynamic fluctuations in attention state$ob$, 6, false, NULL, NULL, true, 1);
  -- p7 [text L1] Population-level studies, like those in the previous section, prompted new ways of thinking about
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Population-level studies, like those in the previous section, prompted new ways of thinking about attentional effects. Specifically, researchers began asking whether firing across a population could serve as a trial-to-trial measure of how attention fluctuates."}]}$ob$::jsonb, $ob$Population-level studies, like those in the previous section, prompted new ways of thinking about attentional effects. Specifically, researchers began asking whether firing across a population could…$ob$, 7, false, NULL, NULL, false, 1);
  -- p8 [text L1] The thinking was that simultaneously recorded neurons could supply many measurements of the same 
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"The thinking was that simultaneously recorded neurons could supply many measurements of the same period of time when a subject is attending (or not) to a visual stimulus. If the responses of many neurons are treated as a set of coordinates, each trial becomes a point in a space with one dimension per neuron, and the trials of a given attention condition form a cloud of points within it. An early, elegant example showed that cues directed at two different spatial locations produce point clouds with different centers. Joining these centers with a line defines an attention axis and projecting a single trial's population response onto this line yields one number describing where the population sat between the two attentional states (Cohen and Maunsell, 2010) (Figure XX)."}]}$ob$::jsonb, $ob$The thinking was that simultaneously recorded neurons could supply many measurements of the same period of time when a subject is attending (or not) to a visual stimulus. If the responses of many…$ob$, 8, false, NULL, NULL, false, 1);
  -- p9 [text L1] Since the axis was built from correct trials alone, missed trials served as an independent test o
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Since the axis was built from correct trials alone, missed trials served as an independent test of whether it tracked attention or merely the cue: on missed trials, projections fell closer to the mean of the opposite attention condition, as though attention had drifted to the wrong location. Projections predicted performance more generally as well — when the population indicated attention to the left, the monkey detected most changes on the left and almost none on the right."}]}$ob$::jsonb, $ob$Since the axis was built from correct trials alone, missed trials served as an independent test of whether it tracked attention or merely the cue: on missed trials, projections fell closer to the…$ob$, 9, false, NULL, NULL, false, 1);
  -- p10 [text L1] Later work from the same group used this population measure to track spatial and feature attenti
  INSERT INTO paragraphs (section_id, content, content_text, order_index, has_animation, animation_id, animation_trigger, is_subsection_header, subsection_level)
  VALUES (v_section_id, $ob${"blocks":[{"type":"text","content":"Later work from the same group used this population measure to track spatial and feature attention simultaneously. Attention axes for spatial attention fluctuated independently in each hemisphere, while those for feature attention were coordinated across both. This is consistent with the effects of spatial and feature attention on individual neurons: spatial attention is localized to neurons representing the attended location, whereas feature attention modulates neurons carrying information about the attended feature regardless of where their receptive fields sit. These differences in cortical extent become relevant when we consider the circuitry that implements attentional effects in the next section."}]}$ob$::jsonb, $ob$Later work from the same group used this population measure to track spatial and feature attention simultaneously. Attention axes for spatial attention fluctuated independently in each hemisphere,…$ob$, 10, false, NULL, NULL, false, 1);

